/**
 * A running Studio HTTP server.
 */
export type StudioServer = {
  /**
   * Shuts the server down and stops accepting new connections.
   */
  close(): void
}

export type StudioServerOptions = {
  /**
   * Handles an incoming request and produces the response to send back.
   */
  handler: (request: Request) => Response | Promise<Response>

  /**
   * Called once the server is ready to accept connections.
   */
  onListen: () => void

  /**
   * The port to listen on.
   */
  port: number
}

/**
 * Starts an HTTP server that delegates incoming requests to `handler`.
 *
 * `GET` requests are answered with the handler's response, streamed back to the
 * client. `HEAD` requests reuse the equivalent `GET` response's status but omit
 * the body. When the handler throws, the server responds with HTTP 500 and the
 * error message as a plain-text body.
 */
export function startStudioServer({ handler, onListen, port }: StudioServerOptions): StudioServer {
  const server = createServer((req, res) => {
    void respond(req, res, handler)
  })

  server.listen(port, onListen)

  return {
    close() {
      server.close()
    },
  }
}

async function respond(
  req: IncomingMessage,
  res: ServerResponse,
  handler: (request: Request) => Response | Promise<Response>,
): Promise<void> {
  const isHead = req.method === 'HEAD'

  try {
    const request = await toWebRequest(req, isHead)
    const response = await handler(request)

    res.statusCode = response.status

    response.headers.forEach((value, key) => {
      res.setHeader(key, value)
    })

    if (isHead || response.body === null) {
      res.end()
      return
    }

    await streamBody(response.body, res)
  } catch (error) {
    console.error('[Prisma Studio]', error)

    res.statusCode = 500
    res.setHeader('access-control-allow-origin', '*')
    res.setHeader('content-type', 'text/plain; charset=utf-8')
    res.end(error instanceof Error ? error.message : String(error))
  }
}

async function toWebRequest(req: IncomingMessage, isHead: boolean): Promise<Request> {
  const host = req.headers.host ?? 'localhost'
  const url = new URL(req.url ?? '/', `http://${host}`)

  // A `HEAD` response must mirror the corresponding `GET` response, so we ask
  // the handler for the `GET` variant and strip the body afterwards.
  const method = isHead ? 'GET' : req.method ?? 'GET'

  const headers = new Headers()
  for (const [key, value] of Object.entries(req.headers)) {
    if (value === undefined) {
      continue
    }

    if (Array.isArray(value)) {
      for (const entry of value) {
        headers.append(key, entry)
      }
    } else {
      headers.set(key, value)
    }
  }

  const hasBody = method !== 'GET' && method !== 'HEAD'

  return new Request(url, {
    method,
    headers,
    body: hasBody ? await readBody(req) : undefined,
  })
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = []

  for await (const chunk of req) {
    chunks.push(chunk as Buffer)
  }

  return Buffer.concat(chunks)
}

async function streamBody(body: ReadableStream<Uint8Array>, res: ServerResponse): Promise<void> {
  const reader = body.getReader()

  try {
    for (;;) {
      const { done, value } = await reader.read()

      if (done) {
        break
      }

      res.write(value)
    }
  } finally {
    res.end()
  }
}
