/**
 * Builds the Studio BFF HTTP handler and starts serving it.
 *
 * The handler serves the Studio HTML shell along with the bundled front-end
 * assets (`/studio.js`, `/studio.css`) directly from the filesystem, so Studio
 * no longer depends on external CDNs. It also exposes the `/bff` API used by the
 * front-end to talk to the database.
 */
function startStudioBff({
  adapter,
  executor,
  port,
  ppgDbInfo,
  protocol,
  version,
  onListen,
}: StartStudioBffOptions): StudioServer {
